HINDU19='https://www.thehindu.com/news/cities/Delhi/coal-case-charges-framed-against-naveen-jindal/article28714614.ece'
IE17='https://indianexpress.com/article/india/cbi-files-final-report-in-coal-scam-case-against-naveen-jindal/'
WSJ='https://en.wikipedia.org/wiki/Savitri_Jindal'
WNJ='https://en.wikipedia.org/wiki/Naveen_Jindal'
